import { ApiClient, validBase } from './api.js';
import { DemoClient, demoUser } from './demo.js';
const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const icons = { book:'▤', explore:'◈', stories:'▥', write:'＋', comments:'☷', settings:'⚙', arrow:'↗' };
let base = localStorage.getItem('scribe-api-base') ?? 'https://scribeboard-api.onrender.com/api/v1';
let client = base ? new ApiClient(base) : new DemoClient();
let cats = [], generation = 0, dirty = false, currentPost = null, lastHash = location.hash || '#explore', busy = false;
const user = () => client.session?.user;
const editor = () => ['EDITOR', 'ADMIN'].includes(user()?.role);
const route = () => { const [path, query] = (location.hash.slice(1) || 'explore').split('?'); return { parts: path.split('/'), q: new URLSearchParams(query) }; };
const name = u => [u?.firstName, u?.lastName].filter(Boolean).join(' ') || 'Guest';
const date = d => d ? new Date(d).toLocaleDateString('en-US', { month:'short', day:'numeric', year:'numeric' }) : '';
const tag = p => `<span class="badge ${p.status === 'PUBLISHED' ? 'green' : ''}">${esc((p.status || 'DRAFT').toLowerCase().replaceAll('_', ' '))}</span>`;
function toast(msg) { $('#toast').textContent = msg; $('#toast').classList.add('show'); clearTimeout(toast.timer); toast.timer = setTimeout(() => $('#toast').classList.remove('show'), 5500); }
function go(hash) { if (dirty && !confirm('Leave this page? Your unsaved changes will be lost.')) return; dirty = false; if (location.hash === '#' + hash) render(); else location.hash = hash; }
function shell() {
 const tab = route().parts[0];
 $('#app').innerHTML = `<aside class="sidebar"><a class="brand" href="#explore"><span class="brand-mark">s<span>•</span></span>ScribeBoard<span class="brand-dot">.</span></a><p class="nav-label">YOUR DAILY DOSE OF IDEAS</p><nav aria-label="Main navigation">${[['explore','Explore','explore'],['stories','My stories','stories'],['write','Write a story','write'],...(editor() ? [['comments','Moderation','comments']] : []),['settings','Settings','settings']].map(([id,label,icon]) => `<a href="#${id}" class="nav-link ${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}><span aria-hidden="true">${icons[icon]}</span>${label}</a>`).join('')}</nav><div class="sidebar-note"><span class="spark">✳</span><h3>A little space.<br>A lot of possibility.</h3><p>Your next great idea<br>starts with a few words.</p><a href="#write">Start writing <span>↗</span></a></div><div class="sidebar-bottom"><a class="nav-link ${tab==='settings'?'active':''}" href="#settings"><span aria-hidden="true">⚙</span>Connection settings</a><div class="mode"><i class="${base?'live':''}"></i>${base?'Connected API':'Demo workspace'}<span>${base?'LIVE':'SAMPLE'}</span></div></div></aside><div class="layout"><header><div class="breadcrumb">Your space for ideas <span>/</span> <strong>${({explore:'Explore',stories:'My stories',write:'Editor',post:'Reading',comments:'Moderation',settings:'Settings'})[tab] || 'Explore'}</strong></div><div class="header-actions">${user()?`<span class="avatar">${esc(user().firstName?.[0])}</span><span class="user-name">${esc(name(user()))}</span><button class="text-button" data-action="logout">Sign out</button>`:`<button class="text-button" data-action="login">Sign in</button><button class="button small" data-action="register">Get started <span>↗</span></button>`}</div></header><main id="main" tabindex="-1"><div class="loading" role="status">Opening your workspace…</div></main><footer>ScribeBoard <span>Thoughts worth sharing.</span><span>${base?'Powered by your ScribeBoard API':'Demo content · Changes stay in this tab'}</span></footer></div>`;
}
function empty(title, text, action='') { return `<section class="empty"><span class="empty-icon">▤</span><h2>${title}</h2><p>${text}</p>${action}</section>`; }
function pages(p) { return p?.totalPages > 1 ? `<div class="pagination"><button class="button secondary" data-page="${p.page-1}" ${!p.hasPrevPage?'disabled':''}>← Previous</button><span>Page ${p.page} of ${p.totalPages}</span><button class="button secondary" data-page="${p.page+1}" ${!p.hasNextPage?'disabled':''}>Next →</button></div>` : ''; }
function illustration(type=0) { return `<div class="art art-${type%4}" aria-hidden="true"><div class="art-circle"></div><div class="art-page"><span></span><span></span><span></span><b>✳</b></div><div class="art-line"></div><i>scribeboard / field notes</i></div>`; }
function card(p, i) { return `<article class="story-card"><a href="#post/${encodeURIComponent(p.id)}" tabindex="-1" aria-hidden="true">${illustration(i)}</a><div class="card-body"><span class="eyebrow">${esc(p.category?.name || 'Journal')}</span><h3><a href="#post/${encodeURIComponent(p.id)}">${esc(p.title)}</a></h3><p>${esc(p.excerpt || p.content?.slice(0,140))}</p><div class="byline"><span class="avatar tiny">${esc(p.author?.firstName?.[0] || 'S')}</span><span>${esc(name(p.author))}</span><span class="read-time">${p.readingTime || 1} min read</span></div></div></article>`; }
async function render() {
 const g=++generation; currentPost=null; shell(); const {parts,q}=route(); const tab=parts[0];
 try {
  if (!cats.length && ['explore','write'].includes(tab)) cats = (await client.request('/categories?limit=100')).data;
  let html='';
  if(tab==='explore') {
   const query = new URLSearchParams({status:'PUBLISHED',limit:'9',page:q.get('page')||'1',sort:q.get('sort')||'-createdAt'});
   if(q.get('search')) query.set('search',q.get('search')); if(q.get('categoryId')) query.set('categoryId',q.get('categoryId'));
   const r=await client.request('/posts?'+query);
   html=`<section class="intro"><div><p class="eyebrow">THE SCRIBEBOARD JOURNAL</p><h1>Good ideas deserve<br>a place to <em>grow.</em></h1><p>Stories, perspectives, and a little inspiration.<br>Find something that stays with you.</p><a class="button" href="#write">Write your first story <span>↗</span></a></div><div class="hero-art" aria-hidden="true"><span class="orbit one"></span><span class="orbit two"></span><div class="hero-paper"><span class="paper-top">A NOTE TO SELF <b>↗</b></span><p>Stay curious.<br>Make things.<br><em>Share your story.</em></p><span class="paper-bottom">EVERY IDEA STARTS SOMEWHERE <b>✳</b></span></div><span class="hero-stamp">IDEAS<br>LIVE HERE</span></div></section><div class="section-heading"><div><p class="eyebrow">THE READING ROOM</p><h2>Fresh perspectives</h2></div><span class="muted">${r.pagination?.total ?? r.data.length} stories to explore</span></div><div class="filters"><div class="chips"><button data-category="" class="chip ${!q.get('categoryId')?'selected':''}">All stories</button>${cats.map(c=>`<button data-category="${esc(c.id)}" class="chip ${q.get('categoryId')===c.id?'selected':''}">${esc(c.name)}</button>`).join('')}</div><form id="search-form" class="search"><label class="sr-only" for="search">Search stories</label><input id="search" name="search" placeholder="Search stories…" maxlength="100" value="${esc(q.get('search'))}"><button aria-label="Search">⌕</button></form></div><div class="sort-row"><span>${q.get('search')?`Results for “${esc(q.get('search'))}”`:'A few good reads for your day.'}</span><label>Sort by <select id="sort"><option value="-createdAt">Newest first</option><option value="title" ${q.get('sort')==='title'?'selected':''}>Title A–Z</option></select></label></div>${r.data.length?`<div class="card-grid">${r.data.map(card).join('')}</div>`:empty('No stories found','Try another search or category.')} ${pages(r.pagination)}`;
  } else if(tab==='settings') html=`<div class="page-heading"><p class="eyebrow">MAKE IT YOURS</p><h1>Connect your workspace.</h1><p>Switch from sample stories to your own ScribeBoard API.</p></div><section class="panel settings-panel"><span class="badge green">${base?'API mode':'Demo mode'}</span><h2>Your backend connection</h2><p>Use the full API address, including <code>/api/v1</code>. Connecting signs you out and keeps your demo posts separate.</p><form id="connection-form"><label for="api-base">API address</label><input id="api-base" name="base" type="url" required placeholder="https://your-api.example.com/api/v1" value="${esc(base)}"><p class="hint">Your backend must allow this website’s origin in its CORS settings: <code>${esc(location.origin)}</code></p><div class="form-error" role="alert"></div><div class="form-actions"><button class="button">Test & connect <span>↗</span></button>${base?'<button type="button" class="button secondary" data-action="demo-mode">Switch to demo</button>':''}</div></form></section><section class="info-note"><h3>Where your work lives</h3><p>Live posts are stored in your backend’s PostgreSQL database. Demo posts are stored only in this browser tab. Login tokens stay in memory, so reloading the page requires signing in again.</p></section>`;
  else if(tab==='post') {
   const p=(await client.request('/posts/'+encodeURIComponent(decodeURIComponent(parts[1]||'')))).data;
   const comments=p.status==='PUBLISHED'?(await client.request('/posts/'+p.id+'/comments?limit=100')).data:[];
   currentPost=p;
   html=`<div class="reader-top"><a href="#explore">← Back to stories</a>${user()&&(user().id===p.authorId||editor())?`<a class="button secondary small" href="#write/${esc(p.id)}">Edit story ↗</a>`:''}</div><article class="reader"><span class="eyebrow">${esc(p.category?.name || 'Journal')}</span>${p.status!=='PUBLISHED'?tag(p):''}<h1>${esc(p.title)}</h1><p class="reader-excerpt">${esc(p.excerpt)}</p><div class="byline"><span class="avatar">${esc(p.author?.firstName?.[0]||'S')}</span><div><strong>${esc(name(p.author))}</strong><div class="muted">${date(p.createdAt)} · ${p.readingTime||1} min read</div></div></div><div class="prose">${esc(p.content).split(/\n\n+/).map(t=>`<p>${t.replaceAll('\n','<br>')}</p>`).join('')}</div><div class="tags">${(p.tags||[]).map(t=>`<span class="chip">${esc(t.tag?.name||t.name)}</span>`).join('')}</div></article><section class="discussion"><h2>The conversation <span class="muted">(${comments.length})</span></h2>${comments.map(c=>`<article class="comment"><strong>${esc(c.author?name(c.author):c.guestName||'Guest')}</strong><span class="muted"> ${date(c.createdAt)}</span><p>${esc(c.content)}</p></article>`).join('')}${p.status==='PUBLISHED'&&p.allowComments?`<form id="comment-form">${!user()?'<div class="two-col"><div><label for="guestName">Name</label><input id="guestName" name="guestName" minlength="2" maxlength="50" required></div><div><label for="guestEmail">Email (kept private)</label><input id="guestEmail" name="guestEmail" type="email" required></div></div>':''}<label for="comment">Add your perspective</label><textarea id="comment" name="content" minlength="2" maxlength="2000" rows="4" required placeholder="What stayed with you?"></textarea><p class="hint">Comments may need approval before appearing.</p><div class="form-error" role="alert"></div><button class="button">Post comment ↗</button></form>`:'<p class="muted">Comments are closed for this story.</p>'}</section>`;
  } else if(!user()) html=empty('A space for your stories','Sign in to write, publish, and manage your work.',`<button class="button" data-action="login">Sign in ↗</button>${!base?'<button class="button secondary" data-action="demo-login">Try the demo workspace</button>':''}`);
  else if(tab==='stories') {
   const query=new URLSearchParams({limit:'10',page:q.get('page')||'1'}); if(q.get('status'))query.set('status',q.get('status'));
   const r=await client.request('/posts/mine?'+query);
   html=`<div class="page-heading split"><div><p class="eyebrow">YOUR WRITING DESK</p><h1>My stories<span class="green-text">.</span></h1><p>From the first thought to the final word.</p></div><a class="button" href="#write">＋ New story</a></div><div class="chips story-tabs">${[['','All stories'],['DRAFT','Drafts'],['PUBLISHED','Published'],['PENDING_REVIEW','In review'],['UNPUBLISHED','Unpublished']].map(([id,n])=>`<button data-status="${id}" class="chip ${(q.get('status')||'')===id?'selected':''}">${n}</button>`).join('')}</div>${r.data.length?`<section class="story-list">${r.data.map(p=>`<article class="story-row"><div><div class="row-meta">${tag(p)}<span>${date(p.updatedAt)}</span></div><h3><a href="#write/${esc(p.id)}">${esc(p.title)}</a></h3><p>${esc(p.excerpt||'Your story is taking shape.')}</p></div><a class="button secondary small" href="#write/${esc(p.id)}">Edit <span>↗</span></a></article>`).join('')}</section>`:empty('Your next story starts here','Give that idea a little room to grow.','<a class="button" href="#write">Write a story ↗</a>')}${pages(r.pagination)}`;
  } else if(tab==='write') {
   const p=parts[1]?(await client.request('/posts/'+encodeURIComponent(decodeURIComponent(parts[1])))).data:null; currentPost=p;
   if(p && p.authorId!==user().id && !editor()) throw new Error('You can only edit your own stories.');
   html=`<div class="page-heading split"><div><p class="eyebrow">THE WRITING DESK</p><h1>${p?'Make it your own.':'Let the words flow.'}</h1></div><a href="#stories" class="text-button">← My stories</a></div><form id="editor-form"><div class="editor-toolbar"><span>${p?tag(p):'<span class="badge">New draft</span>'} <span id="save-state" class="muted">${p?'Saved to workspace':'Not saved yet'}</span></span><div><button class="button secondary" name="intent" value="draft">${p?'Save changes':'Save draft'}</button><button class="button" name="intent" value="publish">${p?.status==='PUBLISHED'?'Update published story':'Publish story'} ↗</button></div></div><div class="editor-grid"><section class="editor-paper"><label for="title">Story title</label><input class="title-input" id="title" name="title" required minlength="5" maxlength="200" placeholder="Every story starts with a title…" value="${esc(p?.title)}"><label for="content">Your story</label><textarea id="content" name="content" required minlength="50" rows="18" placeholder="Start with a thought. See where it takes you.">${esc(p?.content)}</textarea><div class="editor-foot"><span id="word-count">${p?.content?.trim().split(/\s+/).length||0} words</span><span>Plain text · 50 characters minimum</span></div></section><aside class="editor-options"><h3>The details</h3><label for="excerpt">Short description</label><textarea id="excerpt" name="excerpt" maxlength="500" rows="4" placeholder="A little invitation to keep reading…">${esc(p?.excerpt)}</textarea><label for="categoryId">Category</label><select id="categoryId" name="categoryId"><option value="">Uncategorized</option>${cats.map(c=>`<option value="${esc(c.id)}" ${p?.categoryId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><label for="tags">Tags</label><input id="tags" name="tags" placeholder="design, ideas, learning" value="${esc(p?.tags?.map(t=>t.tag?.name||t.name).join(', '))}"><p class="hint">Separate with commas. Up to 10 tags.</p><label class="check"><input type="checkbox" name="allowComments" ${p?.allowComments!==false?'checked':''}> Allow comments</label>${p?`<div class="editor-secondary">${p.status==='PUBLISHED'?'<button type="button" class="text-button" data-action="unpublish">Unpublish story</button>':p.authorId===user().id?'<button type="button" class="text-button" data-action="review">Submit saved story for review</button>':''}<button type="button" class="text-button danger" data-action="delete">Delete story</button></div>`:''}</aside></div><div class="form-error" role="alert"></div></form>`;
  } else if(tab==='comments') {
   if(!editor()) throw new Error('Comment moderation is available to editors and administrators.');
   const query=new URLSearchParams({status:q.get('status')||'PENDING',limit:'20',page:q.get('page')||'1'}); const r=await client.request('/comments?'+query);
   html=`<div class="page-heading"><p class="eyebrow">KEEP THE CONVERSATION THOUGHTFUL</p><h1>Comment moderation.</h1><p>Make room for good conversations.</p></div><div class="chips story-tabs">${['PENDING','APPROVED','REJECTED','SPAM'].map(s=>`<button class="chip ${(q.get('status')||'PENDING')===s?'selected':''}" data-status="${s}">${s.toLowerCase()}</button>`).join('')}</div>${r.data.length?r.data.map(c=>`<article class="panel moderation"><div><span class="eyebrow">${esc(c.post?.title||'Story comment')}</span><h3>${esc(c.author?name(c.author):c.guestName||'Guest')}</h3><p>${esc(c.content)}</p></div><div class="form-actions"><button class="button small" data-moderate="approve" data-id="${esc(c.id)}">Approve</button><button class="button secondary small" data-moderate="reject" data-id="${esc(c.id)}">Reject</button><button class="text-button danger" data-moderate="spam" data-id="${esc(c.id)}">Spam</button></div></article>`).join(''):empty('You’re all caught up','No comments in this queue.')}${pages(r.pagination)}`;
  } else html=empty('Page not found','Let’s get you back to the reading room.','<a class="button" href="#explore">Explore stories</a>');
  if(g!==generation)return; $('#main').innerHTML=html; document.title=`${tab==='post'?currentPost?.title:({explore:'Explore',stories:'My stories',write:'Writing desk',settings:'Connection settings',comments:'Moderation'})[tab]||'Home'} — ScribeBoard`;
 } catch(e) { if(g===generation) $('#main').innerHTML=empty('Something needs attention',esc(e.message),'<button class="button" data-action="retry">Try again</button><a class="button secondary" href="#settings">Connection settings</a>'); }
}
function filter(key,value) { const {parts,q}=route(); value?q.set(key,value):q.delete(key); if(key!=='page') q.delete('page'); go(parts.join('/')+(q.size?'?'+q:'')); }
function auth(register=false) {
 const d=$('#dialog'); d.innerHTML=`<button class="dialog-close" aria-label="Close dialog" data-action="close">×</button><span class="brand-mark">s<span>•</span></span><p class="eyebrow">YOUR NEXT CHAPTER</p><h2>${register?'Make room for your ideas.':'Welcome back.'}</h2><p>${base?'Sign in to your ScribeBoard workspace.':'You’re exploring a demo. Connect your API for real accounts.'}</p>${base?`<form id="auth-form" data-register="${register}">${register?'<div class="two-col"><div><label for="firstName">First name</label><input id="firstName" name="firstName" minlength="2" maxlength="50" autocomplete="given-name" required></div><div><label for="lastName">Last name</label><input id="lastName" name="lastName" minlength="2" maxlength="50" autocomplete="family-name" required></div></div>':''}<label for="email">Email</label><input id="email" name="email" type="email" autocomplete="email" required><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="${register?'new-password':'current-password'}" ${register?'minlength="8"':''} required>${register?'<p class="hint">At least 8 characters, with uppercase, lowercase, and a number.</p>':''}<div class="form-error" role="alert"></div><button class="button full">${register?'Create account':'Sign in'} ↗</button></form><button class="text-button full" data-action="${register?'login':'register'}">${register?'Already have an account? Sign in':'New here? Create an account'}</button>`:'<button class="button full" data-action="demo-login">Try the demo workspace ↗</button><button class="button secondary full" data-action="connect">Connect my backend</button>'}`; if(!d.open)d.showModal();
}
document.addEventListener('click',async e=>{
 const button=e.target.closest('button'); if(!button)return;
 if(button.dataset.category!==undefined)return filter('categoryId',button.dataset.category);
 if(button.dataset.status!==undefined)return filter('status',button.dataset.status);
 if(button.dataset.page)return filter('page',button.dataset.page);
 const a=button.dataset.action;
 if(a==='login'||a==='register')return auth(a==='register');
 if(a==='close')return $('#dialog').close();
 if(a==='connect'){ $('#dialog').close();go('settings');return; }
 if(a==='retry')return render();
 if(a==='demo-login'){if(base)return;client.session={user:demoUser};$('#dialog').close();go('stories');return;}
 if(a==='demo-mode'){if(!confirm('Disconnect from the API and switch to sample content?'))return; base='';localStorage.setItem('scribe-api-base', '');client=new DemoClient();cats=[];go('explore');return;}
 if(busy)return; busy=true;button.disabled=true;
 try {
  if(a==='logout'){if(base)await client.request('/auth/logout',{method:'POST',body:{refreshToken:client.session.refreshToken}});client.session=null;dirty=false;go('explore');toast('Signed out.');}
  if(['delete','unpublish','review'].includes(a)){
   if(dirty)throw new Error('Save your changes before using this action.');
   if(!confirm(a==='delete'?'Permanently delete this story and its comments?':a==='unpublish'?'Remove this story from public reading?':'Submit this saved story for review?'))return;
   await client.request('/posts/'+currentPost.id+(a==='delete'?'':a==='review'?'/submit-review':'/unpublish'),{method:a==='delete'?'DELETE':'POST'});go('stories');toast(a==='delete'?'Story deleted.':'Story status updated.');
  }
  if(button.dataset.moderate){await client.request('/comments/'+button.dataset.id+'/'+button.dataset.moderate,{method:'POST'});await render();toast('Comment updated.');}
 }catch(e){toast(e.message);}finally{busy=false;button.disabled=false;}
});
document.addEventListener('submit',async e=>{
 e.preventDefault(); const form=e.target;if(busy)return;
 if(form.id==='search-form')return filter('search',new FormData(form).get('search').trim());
 const data=Object.fromEntries(new FormData(form));const error=form.querySelector('.form-error');if(error)error.textContent='';
 const buttons=[...form.querySelectorAll('button')];const intent=e.submitter?.value;busy=true;buttons.forEach(b=>b.disabled=true);
 try {
  if(form.id==='connection-form'){const next=validBase(data.base), candidate=new ApiClient(next);await candidate.request('/health');await candidate.request('/categories?limit=1');base=next;localStorage.setItem('scribe-api-base',base);client=candidate;cats=[];go('explore');toast('Connected to your ScribeBoard API.');}
  if(form.id==='auth-form'){const result=await client.request('/auth/'+(form.dataset.register==='true'?'register':'login'),{method:'POST',body:data});client.session=result.data;$('#dialog').close();go('stories');toast('Welcome to your workspace.');}
  if(form.id==='editor-form'){
   const tags=[...new Set(data.tags.split(',').map(t=>t.trim()).filter(Boolean))];if(tags.length>10||tags.some(t=>t.length>50))throw new Error('Use at most 10 tags, each under 51 characters.');
   const payload={title:data.title.trim(),content:data.content.trim(),tags,allowComments:data.allowComments==='on',...(data.excerpt.trim()?{excerpt:data.excerpt.trim()}:currentPost?{excerpt:''}:{})};
   if(payload.title.length<5||payload.content.length<50)throw new Error('Use a title of at least 5 characters and a story of at least 50 characters.');
   if(data.categoryId)payload.categoryId=data.categoryId;else if(currentPost)payload.categoryId=null;
   const saved=(await client.request(currentPost?'/posts/'+currentPost.id:'/posts',{method:currentPost?'PATCH':'POST',body:payload})).data;
   currentPost=saved;dirty=false;
   // Remember a successfully created draft before publishing, so a failed publish cannot create duplicates.
   history.replaceState(null,'','#write/'+saved.id);lastHash=location.hash;
   if(intent==='publish'&&saved.status!=='PUBLISHED'){
    try{await client.request('/posts/'+saved.id+'/publish',{method:'POST'});}catch(e){await render();toast('Draft saved, but publishing failed: '+e.message);return;}
   }
   go('stories');toast(intent==='publish'?'Story published.':'Story saved.');
  }
  if(form.id==='comment-form'){const r=await client.request('/posts/'+currentPost.id+'/comments',{method:'POST',body:data});form.reset();await render();toast(r.data.status==='APPROVED'?'Comment posted.':'Comment submitted for moderation.');}
 }catch(e){if(error)error.textContent=e.message;else toast(e.message);}finally{busy=false;buttons.forEach(b=>b.disabled=false);}
});
document.addEventListener('input',e=>{if(e.target.closest('#editor-form')){dirty=true;$('#save-state').textContent='Unsaved changes';$('#word-count').textContent=($('#content').value.trim().match(/\S+/g)||[]).length+' words';}});
document.addEventListener('change',e=>{if(e.target.id==='sort')filter('sort',e.target.value);});
window.addEventListener('hashchange',()=>{if(dirty&&!confirm('Leave this page? Your unsaved changes will be lost.')){history.replaceState(null,'',lastHash);return;}dirty=false;lastHash=location.hash;render();window.scrollTo(0,0);});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
render();
